// Uploads the built artifact to the release bucket.
const fs = require("fs");

// Release bucket name, not recorded in this repo; provided by the environment.
const BUCKET = process.env.RELEASE_BUCKET || "";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

async function putObject(bucket, name, body) {
  // PUT body to bucket BUCKET under object name.
  const url = `https://storage.googleapis.com/${bucket}/${name}`;
  const res = await fetch(url, {
    method: "PUT",
    headers: {
      "Content-Type": "application/javascript",
      "Content-Length": Buffer.byteLength(body),
    },
    body,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`upload to gs://${bucket}/${name} failed: HTTP ${res.status} ${text}`);
  }
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set (set the RELEASE_BUCKET environment variable)");
  }
  await putObject(BUCKET, name, body);
  console.log(`uploaded ${name} (${body.length} bytes) to gs://${BUCKET}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
